response.content:
{"fixed_function":"def format_completion(self, item: CompletionItem) -> str:
    if item.help:
        # Escape tabs and newlines in the help text to avoid breaking the completion format
        help_text = item.help.replace("\t", "\\t").replace("\n", "\\n")
        return f"{item.type},{item.value}\t{help_text}"
    return f"{item.type},{item.value}""}
